DATE='2026-11-05'
def source(n,title,authors,year,url,typ,access,loc,lim):
 return dict(id=f'MAT-S{n:02}',title=title,authors=authors,year=year,url=url,source_type=typ,access=access,locator=loc,scope_limit=lim,accessed=DATE)
sources=[
source(1,'Early Pottery at 20,000 Years Ago in Xianrendong Cave, China',['Xiaohong Wu','Chi Zhang','Paul Goldberg','David Cohen','Yan Pan','Trina Arpin','Ofer Bar-Yosef'],2012,'https://www.researchgate.net/publication/228089260_Early_Pottery_at_20000_Years_Ago_in_Xianrendong_Cave_China','archaeological','full-text','Science 336:1696–1700; inspected pottery description, dating/context argument, Tables 1–2 and discussion through author-uploaded full-text extraction. DOI 10.1126/science.1218643.','Dates associated deposits, not an invention event; supplementary micromorphology and dating files not independently acquired. No regional diffusion denominator.'),
source(2,'The impact of environmental change on the use of early pottery by East Asian hunter-gatherers',['Alexandre Lucquin','Harry K. Robson','Yvette Eley','Shinya Shoda','Dessislava Veltcheva','Kevin Gibbs','Carl P. Heron','Sven Isaksson','Yastami Nishida','Yasuhiro Taniguchi','Shōta Nakajima','Kenichi Kobayashi','Peter Jordan','Simon Kaner','Oliver E. Craig'],2018,'https://www.pnas.org/doi/full/10.1073/pnas.1803782115','archaeological','full-text','PNAS 115:7931–7936; introduction; Results and Discussion; Table 1; Conclusion; Methods.','801 samples, not 801 statistically independent households; chemical preservation and detectability constrain inference about all foods. Supporting raw datasets not reanalysed.'),
source(3,'The Transition from Bronze to Iron in Canaan: Chronology, Technology, and Context',['Naama Yahalom-Mack','Adi Eliyahu-Behar'],2015,'https://www.researchgate.net/publication/275250407_The_Transition_from_Bronze_to_Iron_in_Canaan_Chronology_Technology_and_Context','archaeological','full-text','Radiocarbon 57:285–305; pp. 286–300, particularly technological analyses, copper production, and discussion; author-uploaded full-text extraction. DOI 10.2458/azu_rc.57.18563.','Several chemical/metallographic datasets are explicitly unpublished in this synthesis. Association of workshops with administrations is an interpretation. Excavation counts are not population adoption rates.'),
source(4,'The earliest use of iron in China',['Donald B. Wagner'],1999,'https://wuecampus.uni-wuerzburg.de/moodle/pluginfile.php/4671985/mod_resource/content/1/Wagner%2C%20Donald%20B.%20The%20earliest%20use%20of%20iron%20in%20China.pdf','scholarly-analysis','full-text','Metals in Antiquity, BAR International Series 792, pp. 1–9; web-layout copy, sections 1, 3 and 4, especially 3.4 and 4.','Older reconstruction retained to document revision, not treated as the latest chronology. Author distinguishes properly published finds from doubtful tomb contexts; diffusion and economic motives remain interpretive.'),
source(5,'Blast Furnaces in Song–Yuan China',['Donald B. Wagner'],2001,'https://donwagner.dk/arch-iron/resources/Wagner2001.pdf','scholarly-analysis','full-text','East Asian Science, Technology, and Medicine 18:41–74; pp. 41–43, 51–53, 58–63, especially p. 42 n. 6 and p. 61.','Combines excavations, translated records and engineering inference; exact mineral-fuel chemistry and product allocation remain uncertain. Older study; not a national output dataset.'),
source(6,'Iron Smelting in Sudan: Experimental Archaeology at The Royal City of Meroe',['Jane Humphris','Michael F. Charlton','Jake Keen','Lee Sauder','Fareed Alshishani'],2018,'https://api.repository.cam.ac.uk/server/api/core/bitstreams/58594bce-8624-430b-822e-bdec34bf76e6/content','experiment','full-text','Journal of Field Archaeology 43(5):399–416; introduction, experimental campaigns, Tables 2–4, Lessons Learned and Conclusion, pp. 412–415. PDF acquired locally and text inspected.','Replica reflects later/post-Meroitic workshops; multiple parameters changed together. Later results described as anecdotal without detailed quantification. Demonstrates a viable reconstruction, not unique ancient operation.'),
source(7,'Fuel selection during long-term ancient iron production in Sudan',['Jane Humphris','Barbara Eichhorn'],2019,'https://www.researchgate.net/publication/332221733_Fuel_selection_during_long-term_ancient_iron_production_in_Sudan','archaeological','full-text','Azania 54(1):33–54; pp. 34–39, 45–50, Tables 1–2, Discussion and Conclusions; full-text author/repository reproduction. DOI 10.1080/0067270X.2019.1578567.','1,754 charcoal fragments across metallurgical and comparison contexts; small and imperfectly matched non-metallurgical sample. Charcoal selection is not a direct census of woodland or proof of management.'),
source(8,'Arsenic Bronze: Dirty Copper or Chosen Alloy? A View from the Americas',['Heather Lechtman'],1996,'https://www.academia.edu/31356952/Lechtman_Arsenic_Bronze_Dirty_Copper_1996','experiment','full-text','Journal of Field Archaeology 23(4):477–514; pp. 477–481, 500–508, Tables 4–6 and Figs. 25–27; full-text extraction inspected.','Controlled modern alloy tests establish properties, not historical motive by themselves. Some elongation measures need more reproducible experiments. Archaeological and political generalisations rely on cited studies not all independently read.'),
source(9,'The Production of Copper–Arsenic Alloys (Arsenic Bronze) by Cosmelting: Modern Experiment, Ancient Practice',['Heather Lechtman','Sabine Klein'],1999,'https://www.scribd.com/document/374679205/Lechtman-H-The-Production-of-Copper-Arsenic-Alloys-by-Co-Smelting','experiment','full-text','Journal of Archaeological Science 26:497–526; abstract, experimental design, Table 11, discussion pp. 523–526; full article text visible through public reproduction. DOI 10.1006/jasc.1998.0324.','Modern experiments with Peruvian ores and archaeologically informed furnace forms; do not identify the actual process at every ancient site. Claims about ancient emissions are not measured ancient exposure.'),
source(10,'Sound, color and meaning in the metallurgy of Ancient West Mexico',['Dorothy Hosler'],1995,'https://www.tandfonline.com/doi/abs/10.1080/00438243.1995.9980295','scholarly-analysis','abstract','World Archaeology 27(1):100–115; publisher abstract inspected; full article inaccessible through attempted publisher link.','Only abstract inspected. It identifies tools/status objects and sound/colour interpretation but cannot support numerical prevalence, detailed alloys, or audit of ethnohistoric passages.'),
source(11,'Ancient West Mexican Metallurgy: South and Central American Origins and West Mexican Transformations',['Dorothy Hosler'],1988,'https://anthrosource.onlinelibrary.wiley.com/doi/abs/10.1525/aa.1988.90.4.02a00040','scholarly-analysis','abstract','American Anthropologist 90(4):832–855; publisher abstract and bibliographic information inspected.','Diffusion argument not independently audited beyond abstract. Its circa AD 800 starting date differs from the circa AD 600 framework in the later paper; neither is used as a securely identified first invention.'),
source(12,'The Glass Making Crucibles from Ile-Ife, SW Nigeria',['Abidemi B. Babalola','Thilo Rehren','Akin Ige','Susan K. McIntosh'],2018,'https://repository.cyi.ac.cy/bitstream/CyI/1939/1/Babalola%20et%20al%202018%20Glassmaking%20crucibles%20Ile-Ife%20JAA%2016.pdf','archaeological','partial-text','Journal of African Archaeology 16:31–59; pp. 31–32 abstract and introduction inspected in PDF extraction; subsequent retrievals timed out. DOI 10.1163/21915784-20180002.','Detailed body tables were not inspected; only explicit abstract-level findings about ten analysed crucibles, refractory clay and estimated 1–7 L capacities are used. Capacity is not annual output.'),
source(13,'Chemical analysis of glass beads from Igbo Olokun, Ile-Ife (SW Nigeria): New light on raw materials, production, and interregional interactions',['Abidemi Babatunde Babalola','Laure Dussubieux','Susan Keech McIntosh','Thilo Rehren'],2018,'https://www.academia.edu/35714341/Chemical_analysis_of_glass_beads_from_Igbo_Olokun_Ile_Ife_SW_Nigeria_New_light_on_raw_materials_production_and_interregional_interactions_Babalola_et_al_2018_JAS_90_','archaeological','full-text','Journal of Archaeological Science 90:92–105; sections 2, 3.4, 4.1–4.3 and 5; Table 3 and discussion of sampling and disturbed deposits. DOI 10.1016/j.jas.2017.12.005.','52 beads selected to cover visible diversity, about 0.5% of excavated assemblage; no statistical population sample. Disturbed deposits and no intact furnace in these units limit chronology and organisation.'),
source(14,'Semi-finished glass from Ile-Ife, Nigeria: implications for the archaeology of glass in sub-Saharan Africa',['Abidemi Babatunde Babalola','Adisa Benjamin Ogunfolakan','Thilo Rehren'],2020,'https://discovery.ucl.ac.uk/id/eprint/10104101/3/Rehren_Babalola%20et%20al%20Antiquity%202020%20final%20version.pdf','archaeological','full-text','Accepted manuscript pp. 1–4; sections 2016 and 2017 investigations, Semi-finished glass, Laboratory analysis, Implications and concluding remarks.','Three museum-store fragments recorded from Igbo Olokun, not newly excavated in sealed contexts. Strong primary-production evidence; unique recipe does not by itself exclude transferred ideas or workers.'),
source(15,'Questioning Diversity (of Iron) in the Workplace: Bloomery Iron, Cast Iron, China and the West',['Yaxiong Liu','Jonathan R. Wood'],2025,'https://intarch.ac.uk/journal/issue69/14/full-text.html','scholarly-analysis','full-text','Internet Archaeology 69; Table 1; sections 2–4, especially cast-iron processing, access to technologies, and concluding social hypotheses. DOI 10.11141/ia.69.14.','Deliberately aggregates China and the West; many dates disputed by its own statement. Cross-craft complements are plausible; broad state-suppression and counterfactual collapse arguments are not accepted here as demonstrated causes.'),
source(16,'The sword that was broken …: The detection of recycled iron in the archaeological record',['McKenzie R. Bentley','Brian Gilmour','A. Mark Pollard'],2023,'https://onlinelibrary.wiley.com/doi/full/10.1111/arcm.12892','scholarly-analysis','full-text','Archaeometry 65(6):1260–1274; Introduction, Iron production and the forms of iron recycling, illustrative artefacts, Conclusions.','Methods-oriented discussion and selected examples, not representative recycling rates. Composite construction can mimic reuse; documentary and modern ethnographic analogies must not be retrojected automatically.')]

def ref(n,loc,supports):return dict(source_id=f'MAT-S{n:02}',locator=loc,supports=supports)
def claim(n,cs,statement,etype,conf,status,refs,counter,limits):
 return dict(id=f'MAT-K{n:02}',case_ids=[f'MAT-C{x:02}' for x in cs],statement=statement,evidence_type=etype,confidence=conf,causal_status=status,sources=refs,counterevidence=counter,inference_limits=limits)
claims=[
claim(1,[1],'Xianrendong pottery-bearing contexts were dated to approximately 20,000–19,000 calibrated years BP, long before farming; this dates surviving use, not the invention of pottery.','archaeological','high','descriptive',[ref(1,'pp. 1697–1699; Tables 1–2','Associated bone/charcoal dates and micromorphological checks of the deposits.')],'The dated materials are associated deposits; some strata were affected by small-scale bioturbation.','No first inventor, unique origin, or regional prevalence follows from this site.'),
claim(2,[1],'Xianrendong fragments document vessel-making among foragers, while exterior burning makes cooking plausible rather than identifying particular foods.','archaeological','medium','descriptive',[ref(1,'pp. 1696–1697','Forager context, temper, forming methods, and burned exterior surfaces.')],'No reconstructed complete vessels or direct residue identification in this study.','Multiple sherds do not establish routine household deployment or mass production.'),
claim(3,[1],'The Japanese sample maintained a strong aquatic-processing association across the Pleistocene–Holocene transition, challenging a simple account in which pottery expanded principally to process newly abundant terrestrial foods.','archaeological','high','mechanism-supported',[ref(2,'Results and Discussion; Table 1; Conclusion','801 samples across 46 sites; conservative aquatic assignments of 73/156 and 256/566 lipid-bearing samples in the two periods.')],'Plant foods and low-lipid contents are imperfectly detectable; functional continuity need not imply unchanged diet.','The sample concerns surviving sampled ceramics, not shares of all food or all households; motives remain interpretive.'),
claim(4,[2],'In the surveyed southern Levant contexts, utilitarian iron appears in Iron I but becomes dominant among classified metal tools/weapons only in Iron IIA, while bronze manufacture continues.','archaeological','medium','descriptive',[ref(3,'pp. 286–294; abstract; Iron Production during the Iron IIA','Contextual counts distinguish initial use from tenth–ninth-century BCE dominance and continuing bronze work.')],'Recovery, corrosion and recycling differ by metal and context.','Archaeological assemblage dominance is not a regional household adoption percentage.'),
claim(5,[2],'The southern Levant evidence weakens an explanation that a general bronze-input shortage forced the transition: copper production continued and the authors report persistent tin-bronze compositions.','archaeological','medium','contested',[ref(3,'pp. 298–299, Copper Production and Bronzeworking','Arabah copper chronology and 95 copper-alloy objects with reported average tin contents maintained around 5–6 wt%.')],'The 95-object chemical dataset was unpublished; scarcity could affect prices or places without changing surviving alloy percentages.','Does not disprove every local or short-lived supply disruption; neither prices nor access distributions are observed.'),
claim(6,[2],'The inspected Canaan study does not find a heat-treatment breakthrough that accounts for iron dominance; carbon content alone is insufficient evidence of deliberate superior steelmaking.','archaeological','medium','contested',[ref(3,'pp. 295–297; p. 300','Metallography, corrosion limits, spontaneous carburisation, and absence of a clear chronological technical leap.')],'Preservation restricts metallography; exceptional objects may escape the sample.','Failure to detect a breakthrough does not prove equal cost, durability, repairability or battlefield performance.'),
claim(7,[2],'Iron work associated with older bronze-working areas and public architecture makes local craft adaptation and administrative support plausible contributors to systematic production.','archaeological','medium','mechanism-supported',[ref(3,'pp. 291–293, 299–300','Spatial/chronological association of metalworking and evidence for urban smelting or forging.')],'Iron I production remains are lacking; imported iron or mobile specialists remain possible.','Workshop location alone neither identifies ownership nor demonstrates compulsion, funding or a state monopoly.'),
claim(8,[3],'Chinese iron history requires separate chronologies for meteoritic objects, bloomery production, casting and practical cast-iron implements; later finds revised earlier accounts of a wholly southern, cast-iron beginning.','scholarly-analysis','high','descriptive',[ref(4,'sections 1, 3.4 and 4','Explicit revision of the author’s previous reconstruction.'),ref(15,'Table 1; sections 2–3','Differentiates first appearance, production and functional use, with disputed dates.')],'Early object dating and production identification remain contested; surviving objects do not locate first smelters.','Supports branching stages, not a definite single transmission route or inventor.'),
claim(9,[3],'Chinese cast-iron production plausibly combined iron smelting with bronze-casting and ceramic/kiln expertise, but the claim that political suppression explains the absence of alternative iron routes remains a hypothesis.','scholarly-analysis','medium','hypothesis',[ref(15,'sections on cast-iron annealing and Access to technology; concluding discussion','Proposes cross-craft integration and discusses moulds, kilns, fuel, labour and state power.'),ref(4,'section 4','Earlier hypothesis connecting agricultural implement forms with iron casting.')],'The 2025 comparison aggregates diverse regions and infers institutions partly from outcomes.','No comparative cost accounts or direct policy enforcement evidence here identify the causal contribution of suppression.'),
claim(10,[3],'Song–Yuan mineral fuel in iron manufacture is supported by texts and anomalously old carbon dates in castings, but a universal shift to coke, or one exact production route, is not established.','scholarly-analysis','medium','descriptive',[ref(5,'pp. 51–53 and 58–61','Su Shi text, sulphur evidence, radiocarbon results, and distinction between smelting and remelting.')],'Charcoal remained possible in other furnaces; carbon can enter during remelting as well as smelting.','Neither national adoption share nor coal/coke ratio follows from the few dated objects.'),
claim(11,[3],'The often-repeated large estimate of Song iron output is not a secure observation: Wagner explicitly rejects the reliability of the extrapolation from state quota figures.','scholarly-analysis','high','descriptive',[ref(5,'p. 42 n. 6','Discusses the roughly 115,000 metric tonne estimate and its flawed underlying assumptions.')],'The author considers the magnitude plausible; criticism does not establish low output.','Do not use disputed output as a denominator for productivity or an adoption rate.'),
claim(12,[4],'Meroe replica smelts improved after changes in ore, air delivery and operation, demonstrating coupled operating constraints rather than the sufficiency of a copied furnace shape.','experiment','high','mechanism-supported',[ref(6,'Tables 2–4; Lessons Learned, pp. 412–415','Failed/low-yield trials, changes to ores and bellows, viable later operation and explicit experimental limitations.')],'Parameters changed together; some later successes lacked detailed records.','Modern reconstructed feasibility does not identify the unique ancient process or provide an ancient output series.'),
claim(13,[4],'Charcoal analysis at Meroe and Hamadab shows persistent, selective use of Acacia type nilotica in metallurgical contexts across a long production history.','archaeological','high','descriptive',[ref(7,'Tables 1–2; pp. 34–39 and 45–47','1,754 analysed charcoal fragments overall; strong metallurgical dominance contrasted with limited non-metallurgical assemblages.')],'Comparison contexts are small and not always contemporaneous; taxonomic identification sometimes tentative.','Persistent fuel selection does not by itself prove woodland management, local sourcing or unchanged production intensity.'),
claim(14,[4],'Meroe’s charcoal assemblages do not establish smelting-induced deforestation; stable fuel access is compatible with management, lower intensity, efficient operation or imports.','archaeological','medium','contested',[ref(7,'pp. 47–50, especially Conclusions','Authors explicitly enumerate alternative supply explanations and unknown exchange range.')],'Ecological degradation could coexist with continued access through a widening collection catchment.','No landscape-scale vegetation reconstruction or procurement-cost series is supplied; absence of a charcoal signal is not proof of ecological harmlessness.'),
claim(15,[5],'Controlled comparisons show that tin bronze’s greater possible hardness does not make it universally superior to arsenical bronze; ductility and sheet-forming performance can favour the latter.','experiment','high','mechanism-supported',[ref(8,'pp. 500–508; Tables 4–6; Figs. 25–27','Mechanical tests and comparison with thin-sheet fabrication traditions.')],'Some tests need more reproducible elongation measurements; alloy concentration and processing strongly affect results.','Modern mechanical advantage is not a complete explanation of archaeological selection or user value.'),
claim(16,[5],'Experimental cosmelting of Peruvian copper oxides with arsenic-bearing sulphide ores produced usable copper–arsenic alloys across multiple mixtures, supplying a feasible alternative to a separate roasting sequence.','experiment','high','descriptive',[ref(9,'pp. 497–499, 523–526; Table 11','Crucible/furnace tests without pre-roasting or added flux and discussion of naturally mixed versus deliberately mixed ores.')],'Feasible experiments do not show which ancient workshops used this process or how often.','No universal origin sequence, automatic intention, ancient occupational-exposure level or cost advantage can be inferred.'),
claim(17,[5],'The Andean history summarized by Lechtman includes continued arsenical-bronze use alongside Inka tin bronze, making coexistence and political distribution more appropriate than a complete superior-alloy replacement story.','scholarly-analysis','medium','mechanism-supported',[ref(8,'pp. 477–479','Regional ore geography, coexistence and interpretation of Inka alloy distribution.')],'Underlying mine-control and closure evidence was not independently audited in this contribution.','Political explanation is plausible but not identified against transport costs, ore supply and task-specific demand.'),
claim(18,[6],'Hosler’s West Mexican studies describe tools as well as objects whose sound and colour mattered, so technological performance cannot be reduced to cutting hardness or military lethality.','scholarly-analysis','medium','mechanism-supported',[ref(10,'abstract','Distinguishes tools/status items and relates bells and metallic colours to ritual and war symbolism.'),ref(8,'pp. 506–508','Mechanical/physical properties and American object selection.')],'The 1995 full text was not acquired; frequency and direct historical passages have not been audited.','Does not establish that every object was ritual, that all consumers shared values, or that productive utility was absent.'),
claim(19,[6],'Hosler proposed South/Central American transmission into West Mexico combined with local technical transformation; this is a claim about selective recombination, not passive copying.','scholarly-analysis','medium','hypothesis',[ref(11,'abstract','Two proposed phases of technical links and explicit local reinterpretation.')],'Only abstract read; dates differ between the 1988 and 1995 formulations. Similarity alone cannot exclude convergence.','Transfer route and carriers remain unverified here; neither isolation nor a complete imported package is assumed.'),
claim(20,[7],'Chemical study of 52 Igbo Olokun beads supports locally distinctive glass groups; related beads elsewhere support exchange, while imported glass at other Ile-Ife sites rules out a wholly isolated setting.','archaeological','high','descriptive',[ref(13,'sections 2, 3.4, 4.1–4.3 and 5; Table 3','Selected-sample chemistry, local raw-material compatibility, regional distribution and other-site soda-lime glass.')],'52 beads are a small selected fraction; deposits disturbed; compatible raw materials are not a uniquely sourced quarry.','No import share for the entire city, market size, annual output or proven transmission of production skills follows.'),
claim(21,[7],'Ile-Ife glass crucibles were specialised ceramic complements; reported usable capacities are evidence of batch capability, not a measurement of sustained industrial throughput.','archaeological','medium','descriptive',[ref(12,'pp. 31–32, abstract','Ten analysed samples, refractory clay, estimated 1–7 L usable capacities.')],'Body tables not acquired; vessel reconstruction and actual fill levels carry uncertainty.','Do not multiply capacity by an invented number of firings, workshops or years.'),
claim(22,[7],'Incompletely reacted glass batch on Ile-Ife crucibles directly strengthens the case for local primary glassmaking, while recipe uniqueness alone cannot establish an origin independent of all external ideas.','archaeological','high','descriptive',[ref(14,'accepted manuscript pp. 2–4, Laboratory analysis and Implications','Residual quartz/feldspar, new reaction phases and heterogeneous glass distinguish raw-batch melting from only remelting finished imports.'),ref(13,'sections 4.2–4.3','Locally compatible recipe and participation in exchange.')],'Museum-store fragments lack newly excavated sealed contexts; authors advance a stronger autonomous-origin interpretation.','Local primary production is better established than the exact invention date, transmission history or subsequent disappearance.'),
claim(23,[2,3],'Recycling and composite manufacture complicate inferences from surviving iron objects to initial production, replacement rates or material scarcity.','synthesis-inference','high','descriptive',[ref(16,'Introduction; Iron production and the forms of iron recycling; Conclusions','Detection problems and selected examples of reused iron; distinction between manufacture and reuse.')],'Some structural evidence is consistent with new composite manufacture as well as recycling.','A methodological warning, not a recycling percentage for either case; selective later parallels are not proof of earlier local practice.'),
claim(24,[1,2,3,4,5,6,7],'Across these purposively selected cases, repeatable processes, complementary crafts and task-specific demand are better-supported comparison variables than a universal ranking of materials.','synthesis-inference','medium','hypothesis',[ref(2,'Results and Conclusion','Functional persistence despite changes in availability.'),ref(6,'Lessons Learned and Conclusion','Coupled operating variables.'),ref(8,'pp. 500–508','Task-dependent alloy properties.'),ref(14,'Laboratory analysis','Local raw-material transformation.')],'Selection emphasises contrasting outcomes and cannot estimate how frequently any mechanism dominated.','A research framework rather than causal identification, universal law or forecast.')]

def case(n,title,region,period,domain,outcome,summary,stages,mechs,counter,ks,ss):
 return dict(id=f'MAT-C{n:02}',title=title,region=region,period=period,domain=domain,outcome=outcome,summary=summary,stages=stages,mechanisms=mechs,counterevidence=counter,claim_ids=[f'MAT-K{x:02}' for x in ks],source_ids=[f'MAT-S{x:02}' for x in ss])
